from oct11_seo_bodies._html import assemble, related


def body() -> str:
    return assemble(
        intro="The <strong>Crohn's Disease Exclusion Diet (CDED)</strong> combines supervised food exclusions with partial enteral nutrition for selected Crohn's disease patients. Online posts often skip formula math, growth checks, and lab monitoring. This page explains phases, typical exclusions, PEN basics, and why CDED is not a DIY cure. Education only.",
        sections=[("Origins and intended Crohn's population", ["CDED emerged from pediatric Crohn's research examining whether specific dietary components plus formula support could assist standard medicines.", 'Adult programs exist at some centers, yet availability varies by city, insurer, and dietitian staffing.', 'Ulcerative colitis was not the primary study population; do not assume identical rules apply to UC without asking.', 'Confirm with your gastroenterologist whether your phenotype matches protocols before buying specialty groceries.']), ('Phase one: strict lists plus formula', ['Early weeks pair a narrow permitted food list with prescribed formula delivering part of daily calories.', 'Volume schedules may split drinks across school or work breaks to limit nausea.', 'Home cooking dominates because restaurant sauces hide emulsifiers excluded in manuals.', 'Stopping early without messaging the team wastes effort and can leave inflammation untreated.']), ('Phase two: widening allowed foods', ['Later phases reintroduce categories while tracking weight, stools, and inflammatory markers.', 'Reintroduction is intentional, not a return to random takeout.', 'Some foods remain optional if they never improved symptoms or labs.', 'Calendar reminders help prevent accidental combo trials during holidays.']), ('Common exclusion categories', ['Manuals often limit certain emulsifiers, thickeners, ultra processed snacks, and selected grains or dairy forms.', 'Permitted fruits, vegetables, proteins, and fats still require portion guidance from your dietitian.', 'Label reading becomes daily homework; brand swaps can silently break rules.', 'Keep photographed labels for clinic review when symptoms drift.']), ('Partial enteral nutrition in plain words', ['Partial enteral nutrition means medical formula supplements meals you still eat from permitted lists.', 'Formulas differ in osmolality, fiber, and lactose; never swap brands without approval.', 'Tube feeding routes exist for patients who cannot drink required volumes orally.', 'Flavor, temperature, and straw pacing tricks improve tolerance for some teens.']), ('Monitoring labs, weight, and growth', ['Expect weight checks, height velocity in children, vitamin D, iron studies, and inflammatory markers on a schedule.', 'Restrictive phases can drop calcium, zinc, or fiber intake before anyone notices clinically.', 'Mental health screening matters when food fear rises during strict weeks.', 'Bring school absence data if fatigue blocks attendance.']), ('CDED versus Mediterranean style eating', ['Mediterranean patterns emphasize olive oil, fish, legumes, and whole grains with flexibility many adults prefer in remission.', 'CDED is stricter early and tied to formula protocols with different goals.', 'Some patients transition toward Mediterranean meals after supervised reintroduction.', 'Compare long term quality of life, not only short term calprotectin drops.']), ('CDED versus low FODMAP trials', ['Low FODMAP targets fermentable carbohydrates for symptom trials with structured reintroduction.', 'Running both experiments simultaneously blames the wrong foods when urgency returns.', 'Sequential trials with professional oversight prevent chaotic elimination.', 'Read <a href="/blog/fodmap-diet-crohns-colitis">FODMAP overview</a> alongside CDED discussions.']), ('Who should avoid self starting CDED', ['Eating disorder history, severe malnutrition, unstable flares, complex strictures, pregnancy, and breastfeeding require individualized medical nutrition therapy first.', 'Patients awaiting surgery may need preoperative optimization rather than sudden exclusions.', 'If formula copays are impossible, ask social work before day one rather than rationing silently.', 'Teens need parental and school nurse coordination for daytime formula access.']), ('Medicines remain central', ['Studies run CDED alongside immunomodulators, biologics, and steroids when clinicians prescribe them.', 'Diet does not automatically replace endoscopy proven healing.', 'Report medication changes to dietitians so timing aligns with infusion nausea or morning immunosuppression.', 'Never stop IBD medicines because an influencer claimed diet alone cleared their photos.']), ('Travel, school, and social logistics', ['Pack labeled bottles, nurse permission forms, and shelf stable backup options for trips.', 'Medical letters help at airport security for powders and liquids.', 'Hosts appreciate knowing you bring safe foods during strict phases without needing full diagnosis stories.', 'Sports practices need hydration plans that respect formula volume limits.']), ('Insurance and formula access', ['Ask early for prescription documentation and diagnosis codes supporting coverage.', 'Denial letters become appeal templates; gastroenterology offices often keep sample letters.', 'Manufacturer assistance programs help qualifying households; social workers know numbers.', 'Track out of pocket costs for tax and flex spending documentation if applicable.']), ('When to pause and call the team', ['Vomiting, fainting, rapid weight loss, inability to keep formula down, or new severe pain needs same day outreach.', 'Psychological distress from restriction also warrants behavioral health support.', 'Use <a href="/flare-help">flare help</a> for clinic escalation paths already published.', 'Do not treat dehydration as willpower failure.']), ('Documenting progress for visits', ['Track formula ounces, permitted meals, stool count, pain scores, and missed work or school days.', 'Photos of ingredient labels help dietitians spot hidden emulsifiers.', 'IBDPal logs can align formula intake with symptom spikes for clearer stories.', 'One page summaries beat long unstructured portal novels.']), ('Talking with school nurses and coaches', ['Provide written formula schedules and emergency contact numbers before semester starts.', 'Coaches need heat plans that respect bathroom access during strict phases.', 'Nurses store formula in labeled bins with expiration dates checked monthly.', 'Excused absences for infusion days should align with FMLA style school notes when applicable.']), ('Sibling and family meal planning', ['Separate pots are not always required; modular plates let siblings add bread while CDED plate stays clean.', 'Explain to siblings that exclusion phases are medical, not punishment for cheating on homework.', 'Family meeting minutes prevent arguments about hidden snack cabinets.', 'Grandparents benefit from printed allowed snack lists before visits.']), ('Emotional resilience during restriction', ['Name frustration without guilt; restrictive phases are temporary tools, not identity.', 'Behavioral health can teach coping scripts for pizza parties at school.', 'Celebrate small adherence wins like finishing formula volume targets.', 'If restriction triggers binge patterns, pause protocol with team guidance.']), ('Formula intolerance troubleshooting', ['Nausea may improve with colder sips, smaller volumes every twenty minutes, or anti nausea meds approved by GI.', 'Diarrhea after formula may reflect osmolality mismatch rather than failure of CDED concept.', 'Lactose free formula switches exist when teams agree.', 'Never dilute formula beyond instructions to make taste tolerable.']), ('Refeeding anxiety after hospital stays', ['Hospitalized patients may restart CDED only after inpatient team clears oral intake.', 'Transition from IV nutrition to PEN requires slow step ups documented daily.', 'Fear of eating after severe flares is common; exposure plans with therapists help.', 'Weight gain targets should be explicit on discharge papers.']), ('Research participation and registries', ['Some centers invite patients into CDED studies with consent forms explaining risks.', 'Participation is optional and should not pressure families already overwhelmed.', 'Ask how study data privacy works before enrolling.', 'Community registries online are not substitutes for clinic supervised CDED.']), ('Cooking skills that reduce emulsifier slips', ['Simple grilled proteins, steamed vegetables, and fruit bowls appear often in permitted lists.', 'Batch roast vegetables without bottled sauces containing forbidden additives.', 'Learn three backup dinners you can cook half asleep during busy weeks.', 'Slow cookers help tenderness without restaurant mystery ingredients.']), ('When CDED is not working on schedule', ['Persistent weight loss or rising calprotectin despite adherence triggers protocol revision.', 'Teams may pivot to exclusive enteral nutrition temporarily or adjust biologics instead of blaming patients.', 'Honesty about accidental slips helps dietitians troubleshoot faster than hidden shame.', 'Second opinions remain valid if communication feels stuck.']), ('Weekly team huddle suggestions', ['Schedule fifteen minute weekly check ins with caregivers during strict CDED phases.', 'Review formula inventory, school forms, and upcoming social events that need backup meals.', 'Note mood changes early so behavioral support can join before crises.', 'End huddles with one praise and one adjustment rather than only criticism.']), ('Celebrating phase completion', ['Mark phase transitions with non food treats like movies or games to reduce food centric reward loops.', 'Document what foods returned smoothly for future flares reference.', 'Thank clinicians and dietitians who supervised; adherence took a village.', 'Pause before jumping into another restrictive internet diet immediately after CDED ends.']), ('Digital community caution', ['Forums often mix CDED with unrelated carnivore or cleanse trends; filter aggressively.', 'Screenshot questions for your dietitian instead of accepting forum consensus as law.', 'Block accounts that shame formula use or medical care.', 'Local in person support groups may feel safer than global comment threads.']), ('Kitchen equipment that helps', ["Immersion blenders smooth soups when chewing hurts during Crohn's flares on CDED.", 'Digital scales measure formula powder accurately unlike heaping scoops.', 'Glass meal prep containers reduce staining from turmeric heavy allowed recipes.', 'Label makers clarify which jar is yours in shared fridges.']), ('Nighttime formula scheduling', ['Splitting formula volume after dinner and before bed reduces reflux for some teens.', 'Elevate head slightly if nighttime regurgitation appears after late formula.', 'Brush teeth after sweet formula to protect enamel during long protocols.', 'Alarm reminders help tired adolescents finish required ounces.']), ('Athletics and CDED energy', ['Student athletes may need higher formula calories on practice days; adjust with dietitian math.', 'Electrolyte losses in sweat still matter when formula already feels heavy.', 'Coach communication prevents forced dehydration practices during strict phases.', 'Return to sport timelines after hospitalization belong in writing from clinicians.']), ('Portal message habits during CDED', ['Batch non urgent CDED questions into one weekly portal note so nurses can answer thoroughly.', 'Attach formula can photos when insurance requests documentation.', 'Mark messages urgent only for vomiting, fainting, or inability to drink prescribed volume.', 'Save replies in a folder titled CDED year for future flare reference.']), ('Peer support without comparison traps', ['Other families may finish CDED phases faster; your timeline is medical not competitive.', 'Share tips with consent, not as pressure to cheat on formula volume.', 'Pediatric psychologists facilitate healthy peer groups when available.', 'Adult online groups need moderation filters against dangerous shortcuts.']), ('Documenting questions between visits', ['Keep running question list in phone notes: formula brand, portion, symptom, school issue.', 'Send portal batch messages weekly instead of panicked midnight fragments.', 'Attach photos of legal labels when unsure about additives.', 'Empty the list during appointments so nothing gets lost.']), ('Seasonal produce within allowed lists', ['Farmer market trips can fit CDED when you know permitted fruits and vegetables.', 'Wash produce thoroughly; immunosuppression raises food safety stakes.', 'Freeze permitted berries for smoothies that still meet texture rules.', 'Seasonal variety prevents flavor burnout during long protocols.']), ('Closing planning notes for your next clinic visit', ['Print or bookmark the sections that matched your week, cross out what did not, and bring one page of questions instead of relying on memory in a rushed appointment.', 'Ask for written flare and remission targets so home experiments stay aligned with scope results, calprotectin trends, and the medicine plan you already follow.', 'If a paragraph felt confusing, note the heading in your portal message so clinicians know exactly where you need clearer guidance rather than a vague request for help.', 'Small steady steps beat dramatic overhauls that collapse after three days; consistency of logging and follow up usually matters more than perfect adherence to internet lists.'])],
        clinic_quote="Is CDED appropriate for my Crohn's phenotype? If yes, who prescribes PEN, which formula fits my needs, and what labs will we track during each phase?",
        faqs=[('Can CDED replace biologics?', 'No. CDED is studied with standard IBD care, not as a guaranteed medicine substitute.'), ('Can adults access CDED?', 'Some adult centers offer supervised pathways; ask an IBD dietitian locally.'), ('Is CDED the same as SCD?', 'No. Specific Carbohydrate Diet uses different rules and evidence.'), ('What if formula taste is awful?', 'Ask about flavor trials and pacing before abandoning prescribed volume.')],
        related_html=related(
            ("Crohn's diet overview", "/blog/crohns-diet-overview-ibd"),
            ("Mediterranean diet notes", "/blog/mediterranean-diet-autoimmune"),
            ("SCD overview", "/blog/specific-carbohydrate-diet-scd-ibd"),
            ("IBD nutrition hub", "/ibd-nutrition"),
        ),
        closing=["CDED is a structured tool some Crohn's teams use with clear start and stop rules, not a moral test of willpower."],
    )
